--
-- Table structure for table `energy_consumption_old`
--

DROP TABLE IF EXISTS `energy_consumption_old`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `energy_consumption_old` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `building_id` varchar(50) DEFAULT NULL COMMENT '建筑编号',
  `meter_id` varchar(50) DEFAULT NULL COMMENT '设备编号',
  `timestamp` datetime DEFAULT NULL COMMENT '监测时间',
  `electricity` float DEFAULT NULL COMMENT '用电量(kWh)',
  `water` float DEFAULT NULL COMMENT '用水量(m³)',
  `supply_temp` float DEFAULT NULL COMMENT '出水温度(℃)',
  `return_temp` float DEFAULT NULL COMMENT '回水温度(℃)',
  `ambient_temp` float DEFAULT NULL COMMENT '环境温度(℃)',
  `humidity` float DEFAULT NULL COMMENT '湿度(%RH)',
  `occupancy` float DEFAULT NULL COMMENT '人员密度(人/100㎡)',
  `is_anomaly` tinyint(1) DEFAULT '0' COMMENT '是否异常',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_building_time` (`building_id`,`timestamp`),
  KEY `idx_meter_time` (`meter_id`,`timestamp`),
  CONSTRAINT `energy_consumption_old_ibfk_1` FOREIGN KEY (`building_id`) REFERENCES `buildings_old` (`id`) ON DELETE CASCADE,
  CONSTRAINT `energy_consumption_old_ibfk_2` FOREIGN KEY (`meter_id`) REFERENCES `meters_old` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='能耗数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

